import{_ as e}from"./plugin-vue_export-helper-c27b6911.js";import{o as s,c as n,e as a}from"./app-89d18e81.js";const i={},o=a(`<h1 id="git-团队协作与进阶工作流" tabindex="-1"><a class="header-anchor" href="#git-团队协作与进阶工作流" aria-hidden="true">#</a> Git 团队协作与进阶工作流</h1><p>在团队开发中，仅仅会 <code>add</code> 和 <code>commit</code> 是不够的。如何高效管理分支、处理突发 Bug 以及解决冲突，是进阶开发者的必经之路。</p><h2 id="_1-核心场景-紧急任务切换-git-stash" tabindex="-1"><a class="header-anchor" href="#_1-核心场景-紧急任务切换-git-stash" aria-hidden="true">#</a> 1. 核心场景：紧急任务切换 (Git Stash)</h2><p><strong>场景描述</strong>：你正在 <code>feature-login</code> 分支开发一个大功能，代码写了一半（还不能提交），这时线上突然报了一个严重 Bug，需要你立刻切回 <code>master</code> 分支去修复。</p><p><strong>解决方案</strong>：</p><ol><li><strong>保存当前进度</strong>：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> stash  <span class="token comment"># 暂时把改动存入堆栈，工作区会变干净</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><strong>切回主分支修复 Bug</strong>：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout master
<span class="token function">git</span> pull origin master
<span class="token function">git</span> checkout <span class="token parameter variable">-b</span> hotfix-bug-123
<span class="token comment"># ... 进行修复 ...</span>
<span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;fix: 修复了 XXX 崩溃问题&quot;</span>
<span class="token function">git</span> checkout master
<span class="token function">git</span> merge hotfix-bug-123
<span class="token function">git</span> push origin master
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><strong>回到功能分支并还原进度</strong>：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout feature-login
<span class="token function">git</span> stash pop  <span class="token comment"># 将之前存入堆栈的改动重新应用到当前分支</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><hr><h2 id="_2-团队协作主流工作流-git-flow" tabindex="-1"><a class="header-anchor" href="#_2-团队协作主流工作流-git-flow" aria-hidden="true">#</a> 2. 团队协作主流工作流：Git Flow</h2><p>在团队中，通常遵循以下分支管理规范：</p><ul><li><strong>master (main)</strong>：主分支，永远保持稳定，随时可发布到生产环境。</li><li><strong>develop</strong>：开发主分支，所有新功能的起点。</li><li><strong>feature/</strong>*：功能分支，从 <code>develop</code> 拉取，完成后合并回 <code>develop</code>。</li><li><strong>hotfix/</strong>*：紧急修复分支，从 <code>master</code> 拉取，修复后合并回 <code>master</code> 和 <code>develop</code>。</li></ul><h3 id="协作流程案例" tabindex="-1"><a class="header-anchor" href="#协作流程案例" aria-hidden="true">#</a> 协作流程案例：</h3><ol><li><strong>领任务</strong>：从 <code>develop</code> 分支拉出一个新分支 <code>feature-ui</code>。</li><li><strong>开发与提交</strong>：遵循“小步快跑”原则，多次小提交。</li><li><strong>代码审查 (Code Review)</strong>：推送到远程后，在 GitHub/GitLab 上发起 <strong>Pull Request (PR)</strong> 或 <strong>Merge Request (MR)</strong>。</li><li><strong>合并</strong>：其他成员 Review 通过后，将代码合并到 <code>develop</code>。</li></ol><hr><h2 id="_3-保持分支最新-rebase-vs-merge" tabindex="-1"><a class="header-anchor" href="#_3-保持分支最新-rebase-vs-merge" aria-hidden="true">#</a> 3. 保持分支最新：Rebase vs Merge</h2><p><strong>场景描述</strong>：你在开发 <code>feature-x</code> 时，同事已经在 <code>develop</code> 提交了很多代码。为了避免最后合并时冲突太多，你需要定期同步 <code>develop</code> 的改动。</p><h3 id="方式-a-merge-生成一个新的合并节点" tabindex="-1"><a class="header-anchor" href="#方式-a-merge-生成一个新的合并节点" aria-hidden="true">#</a> 方式 A：Merge (生成一个新的合并节点)</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout feature-x
<span class="token function">git</span> merge develop
<span class="token comment"># 优点：记录完整，适合最后功能完成时的合并。</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方式-b-rebase-变基-推荐用于同步最新代码" tabindex="-1"><a class="header-anchor" href="#方式-b-rebase-变基-推荐用于同步最新代码" aria-hidden="true">#</a> 方式 B：Rebase (变基，推荐用于同步最新代码)</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> checkout feature-x
<span class="token function">git</span> rebase develop
<span class="token comment"># 优点：提交历史会变成一条直线，非常整洁。</span>
<span class="token comment"># 注意：严禁在公共主分支（如 master）上使用 rebase。</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_4-处理冲突-conflict-resolution" tabindex="-1"><a class="header-anchor" href="#_4-处理冲突-conflict-resolution" aria-hidden="true">#</a> 4. 处理冲突 (Conflict Resolution)</h2><p><strong>场景描述</strong>：当你执行 <code>merge</code> 或 <code>rebase</code> 时，如果两个人修改了同一行代码，Git 会停下来让你手动解决。</p><p><strong>解决步骤</strong>：</p><ol><li><strong>查看冲突文件</strong>：Git 会在冲突的地方标记 <code>&lt;&lt;&lt;&lt;&lt;&lt;&lt; HEAD</code> 和 <code>&gt;&gt;&gt;&gt;&gt;&gt;&gt;</code>。</li><li><strong>手动编辑</strong>：选择保留哪份代码，或者结合两份代码。</li><li><strong>继续操作</strong>：<div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">git</span> <span class="token function">add</span> <span class="token operator">&lt;</span>文件名<span class="token operator">&gt;</span>
<span class="token comment"># 如果是 merge：</span>
<span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;fix: resolve conflict&quot;</span>
<span class="token comment"># 如果是 rebase：</span>
<span class="token function">git</span> rebase <span class="token parameter variable">--continue</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><hr><h2 id="_5-实用技巧-cherry-pick-拣选提交" tabindex="-1"><a class="header-anchor" href="#_5-实用技巧-cherry-pick-拣选提交" aria-hidden="true">#</a> 5. 实用技巧：Cherry-pick (拣选提交)</h2><p><strong>场景描述</strong>：你在 <code>develop</code> 分支修了一个 Bug，但是这个 Bug 同时也存在于 <code>master</code>，你不想合并整个 <code>develop</code> 分支到 <code>master</code>，只想把这一个特定的提交挪过去。</p><p><strong>操作</strong>：</p><ol><li>找到该提交的 ID (<code>git log</code>)。</li><li>切到 <code>master</code>：<code>git checkout master</code>。</li><li>执行：<code>git cherry-pick &lt;commit-id&gt;</code>。</li></ol><hr><h2 id="总结-团队开发好习惯" tabindex="-1"><a class="header-anchor" href="#总结-团队开发好习惯" aria-hidden="true">#</a> 总结：团队开发好习惯</h2><ul><li><strong>频繁 Pull</strong>：开始工作前先 <code>git pull</code>，减少冲突。</li><li><strong>规范 Commit</strong>：使用 <code>feat:</code>, <code>fix:</code>, <code>docs:</code> 等前缀，让人一眼看出提交性质。</li><li><strong>不要直接推 Master</strong>：所有代码必须经过分支合并和 Review。</li><li><strong>善用 <code>.gitignore</code></strong>：不要把 <code>node_modules</code> 或本地配置文件推上去。</li></ul>`,32),t=[o];function c(r,d){return s(),n("div",null,t)}const p=e(i,[["render",c],["__file","collaboration.html.vue"]]);export{p as default};
